#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec / 1e9;
}

int main() {
    const size_t N = 40960000;
    unsigned char *pt = malloc(N);
    unsigned char *ct = malloc(N + 64);
    unsigned char key[32], nonce[12], aad[32];
    memset(pt, 1, N);
    memset(key, 2, 32);
    memset(nonce, 3, 12);
    memset(aad, 4, 32);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER *cipher = EVP_chacha20_poly1305();
    int outl = 0, tmplen = 0;

    /* warmup */
    EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
    EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)N);
    EVP_EncryptFinal_ex(ctx, ct + outl, &tmplen);
    unsigned char tag[16];
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);

    double t0 = now();
    int reps = 10;
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)N);
        EVP_EncryptFinal_ex(ctx, ct + outl, &tmplen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    double dt = now() - t0;
    printf("reinit each time: %.1f ms/op, %.0f MB/s\n", dt/reps*1000, reps*40.96/dt);

    t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)N);
    }
    dt = now() - t0;
    printf("update only: %.1f ms/op, %.0f MB/s\n", dt/reps*1000, reps*40.96/dt);

    /* no aad */
    t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)N);
        EVP_EncryptFinal_ex(ctx, ct + outl, &tmplen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    dt = now() - t0;
    printf("no aad: %.1f ms/op, %.0f MB/s\n", dt/reps*1000, reps*40.96/dt);

    return 0;
}
