#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <openssl/evp.h>

#define N (40960000)
static unsigned char *pt, *ct;
static unsigned char key[32], nonce[12];
static int nthreads;

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec/1e9;}

typedef struct { int id; } Arg;

void *worker(void *p){
    Arg *a = p;
    size_t chunk = (N / nthreads);
    chunk -= chunk % 64;
    size_t start = a->id * chunk;
    size_t end = (a->id == nthreads-1) ? N : start + chunk;
    unsigned char localnonce[16];
    unsigned int counter = (unsigned)(start/64) + 1;
    localnonce[0]=counter&0xff; localnonce[1]=(counter>>8)&0xff; localnonce[2]=(counter>>16)&0xff; localnonce[3]=(counter>>24)&0xff;
    memcpy(localnonce+4, nonce, 12);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, key, localnonce);
    int outl=0;
    EVP_EncryptUpdate(ctx, ct+start, &outl, pt+start, (int)(end-start));
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main(){
    pt = malloc(N); ct = malloc(N+64);
    memset(pt,1,N); memset(key,2,32); memset(nonce,3,12);
    for (nthreads = 1; nthreads <= 8; nthreads++){
        pthread_t th[16]; Arg args[16];
        /* warmup */
        for(int i=0;i<nthreads;i++){args[i].id=i; pthread_create(&th[i],NULL,worker,&args[i]);}
        for(int i=0;i<nthreads;i++) pthread_join(th[i],NULL);
        double t0=now();
        int reps=6;
        for(int r=0;r<reps;r++){
            for(int i=0;i<nthreads;i++){args[i].id=i; pthread_create(&th[i],NULL,worker,&args[i]);}
            for(int i=0;i<nthreads;i++) pthread_join(th[i],NULL);
        }
        double dt=now()-t0;
        printf("%d threads: %.1f ms/op, %.0f MB/s\n", nthreads, dt/reps*1000, reps*40.96/dt);
    }
    return 0;
}
EOF
