#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <immintrin.h>
#include <openssl/evp.h>

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec/1e9;}

/* 4-way ChaCha20 quarter round on AVX2 vectors holding one 32-bit word of 8 blocks */
#define ROT(v, n) (_mm256_or_si256(_mm256_slli_epi32(v, n), _mm256_srli_epi32(v, 32-(n))))
#define QR(a,b,c,d) do { \
    a = _mm256_add_epi32(a, b); d = _mm256_xor_si256(d, a); d = ROT(d, 16); \
    c = _mm256_add_epi32(c, d); b = _mm256_xor_si256(b, c); b = ROT(b, 12); \
    a = _mm256_add_epi32(a, b); d = _mm256_xor_si256(d, a); d = ROT(d, 8); \
    c = _mm256_add_epi32(c, d); b = _mm256_xor_si256(b, c); b = ROT(b, 7); \
} while(0)

/* process 8 blocks (512 bytes) per call, 2 AVX2 vectors of 8 lanes? We use 8 lanes of 32-bit = 8 blocks. */
static void chacha20_8blocks(const unsigned char key[32], const unsigned char nonce[12],
                             unsigned int counter, const unsigned char in[512], unsigned char out[512]){
    __m256i x0,x1,x2,x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14,x15;
    unsigned int k[8];
    memcpy(k, key, 32);
    unsigned int n0,n1,n2;
    memcpy(&n0, nonce, 4); memcpy(&n1, nonce+4, 4); memcpy(&n2, nonce+8, 4);

    x0 = _mm256_set1_epi32(0x61707865);
    x1 = _mm256_set1_epi32(0x3320646e);
    x2 = _mm256_set1_epi32(0x79622d32);
    x3 = _mm256_set1_epi32(0x6b206574);
    x4 = _mm256_set1_epi32(k[0]);
    x5 = _mm256_set1_epi32(k[1]);
    x6 = _mm256_set1_epi32(k[2]);
    x7 = _mm256_set1_epi32(k[3]);
    x8 = _mm256_set1_epi32(k[4]);
    x9 = _mm256_set1_epi32(k[5]);
    x10= _mm256_set1_epi32(k[6]);
    x11= _mm256_set1_epi32(k[7]);
    x12= _mm256_setr_epi32(counter, counter+1, counter+2, counter+3, counter+4, counter+5, counter+6, counter+7);
    x13= _mm256_set1_epi32(n0);
    x14= _mm256_set1_epi32(n1);
    x15= _mm256_set1_epi32(n2);

    __m256i s0=x0,s1=x1,s2=x2,s3=x3,s4=x4,s5=x5,s6=x6,s7=x7,s8=x8,s9=x9,s10=x10,s11=x11,s12=x12,s13=x13,s14=x14,s15=x15;
    for(int i=0;i<10;i++){
        QR(x0,x4,x8,x12); QR(x1,x5,x9,x13); QR(x2,x6,x10,x14); QR(x3,x7,x11,x15);
        QR(x0,x5,x10,x15); QR(x1,x6,x11,x12); QR(x2,x7,x8,x13); QR(x3,x4,x9,x14);
    }
    x0=_mm256_add_epi32(x0,s0); x1=_mm256_add_epi32(x1,s1); x2=_mm256_add_epi32(x2,s2); x3=_mm256_add_epi32(x3,s3);
    x4=_mm256_add_epi32(x4,s4); x5=_mm256_add_epi32(x5,s5); x6=_mm256_add_epi32(x6,s6); x7=_mm256_add_epi32(x7,s7);
    x8=_mm256_add_epi32(x8,s8); x9=_mm256_add_epi32(x9,s9); x10=_mm256_add_epi32(x10,s10); x11=_mm256_add_epi32(x11,s11);
    x12=_mm256_add_epi32(x12,s12); x13=_mm256_add_epi32(x13,s13); x14=_mm256_add_epi32(x14,s14); x15=_mm256_add_epi32(x15,s15);

    /* transpose 8x16 matrix of 32-bit words into 8 blocks of 16 words. Use scalar for correctness first. */
    unsigned int w[16][8];
    _mm256_storeu_si256((__m256i*)w[0], x0); _mm256_storeu_si256((__m256i*)w[1], x1);
    _mm256_storeu_si256((__m256i*)w[2], x2); _mm256_storeu_si256((__m256i*)w[3], x3);
    _mm256_storeu_si256((__m256i*)w[4], x4); _mm256_storeu_si256((__m256i*)w[5], x5);
    _mm256_storeu_si256((__m256i*)w[6], x6); _mm256_storeu_si256((__m256i*)w[7], x7);
    _mm256_storeu_si256((__m256i*)w[8], x8); _mm256_storeu_si256((__m256i*)w[9], x9);
    _mm256_storeu_si256((__m256i*)w[10], x10); _mm256_storeu_si256((__m256i*)w[11], x11);
    _mm256_storeu_si256((__m256i*)w[12], x12); _mm256_storeu_si256((__m256i*)w[13], x13);
    _mm256_storeu_si256((__m256i*)w[14], x14); _mm256_storeu_si256((__m256i*)w[15], x15);

    for(int b=0;b<8;b++){
        unsigned char block[64];
        for(int j=0;j<16;j++) memcpy(block+4*j, &w[j][b], 4);
        const unsigned char *pi = in + 64*b;
        unsigned char *po = out + 64*b;
        for(int j=0;j<64;j++) po[j] = pi[j] ^ block[j];
    }
}

int main(){
    size_t N = 40960000; N -= N % 512;
    unsigned char *in = aligned_alloc(64, N);
    unsigned char *out = aligned_alloc(64, N);
    memset(in, 1, N);
    unsigned char key[32], nonce[12];
    memset(key, 2, 32); memset(nonce, 3, 12);

    /* warmup */
    for(size_t off=0; off<N; off+=512) chacha20_8blocks(key, nonce, (unsigned)(off/64)+1, in+off, out+off);

    double t0 = now();
    int reps = 4;
    for(int r=0;r<reps;r++)
        for(size_t off=0; off<N; off+=512) chacha20_8blocks(key, nonce, (unsigned)(off/64)+1, in+off, out+off);
    double dt = now()-t0;
    printf("avx2 8-block scalar transpose: %.1f ms/op, %.0f MB/s\n", dt/reps*1000, reps*(N/1e6)/dt);

    /* correctness vs openssl for first 512 bytes */
    unsigned char ref[512];
    unsigned char fullnonce[16];
    unsigned int ctr = 1;
    memcpy(fullnonce, &ctr, 4); memcpy(fullnonce+4, nonce, 12);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outl=0;
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, key, fullnonce);
    EVP_EncryptUpdate(ctx, ref, &outl, in, 512);
    printf("match first 512: %d\n", memcmp(ref, out, 512)==0);
    return 0;
}
EOF
