#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <immintrin.h>
#include <openssl/evp.h>

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec/1e9;}

#define ROT(v,n) (_mm256_or_si256(_mm256_slli_epi32(v,n), _mm256_srli_epi32(v,32-(n))))
#define QR(a,b,c,d) do{ \
    a=_mm256_add_epi32(a,b); d=_mm256_xor_si256(d,a); d=ROT(d,16); \
    c=_mm256_add_epi32(c,d); b=_mm256_xor_si256(b,c); b=ROT(b,12); \
    a=_mm256_add_epi32(a,b); d=_mm256_xor_si256(d,a); d=ROT(d,8); \
    c=_mm256_add_epi32(c,d); b=_mm256_xor_si256(b,c); b=ROT(b,7); \
} while(0)

/* Transpose 8 lanes x 16 words into block order using unpack/permute, then xor with input.
   Layout: lane b holds block b. We want out bytes grouped per block. */
static inline void store_xor_8(__m256i w[16], const unsigned char *in, unsigned char *out){
    /* First transpose within 128-bit lanes: each lane has 4 blocks. */
    __m256i t[16];
    for(int i=0;i<16;i+=2){
        t[i]   = _mm256_unpacklo_epi32(w[i], w[i+1]);
        t[i+1] = _mm256_unpackhi_epi32(w[i], w[i+1]);
    }
    __m256i u[16];
    for(int i=0;i<16;i+=4){
        u[i]   = _mm256_unpacklo_epi64(t[i], t[i+2]);
        u[i+1] = _mm256_unpackhi_epi64(t[i], t[i+2]);
        u[i+2] = _mm256_unpacklo_epi64(t[i+1], t[i+3]);
        u[i+3] = _mm256_unpackhi_epi64(t[i+1], t[i+3]);
    }
    /* Now interleave the two 128-bit lanes so each 256-bit register holds 2 blocks? 
       Simpler and still fast: extract 128-bit lanes and store per block. */
    for(int lane=0; lane<2; lane++){
        __m128i r[16];
        for(int i=0;i<16;i++){
            r[i] = lane ? _mm256_extracti128_si256(u[i],1) : _mm256_castsi256_si128(u[i]);
        }
        /* r[4*k + b] holds word group; each r[i] holds 4 consecutive words of one block? 
           After the two unpacks, u[4*b + k] ... let's just verify empirically and fall back. */
        (void)r;
    }
    /* Scalar fallback path kept out; use a fast store via per-lane extract. */
    unsigned int tmp[16][8];
    for(int i=0;i<16;i++) _mm256_storeu_si256((__m256i*)tmp[i], w[i]);
    for(int b=0;b<8;b++){
        __m256i v0 = _mm256_setr_epi32(tmp[0][b],tmp[1][b],tmp[2][b],tmp[3][b],tmp[4][b],tmp[5][b],tmp[6][b],tmp[7][b]);
        __m256i v1 = _mm256_setr_epi32(tmp[8][b],tmp[9][b],tmp[10][b],tmp[11][b],tmp[12][b],tmp[13][b],tmp[14][b],tmp[15][b]);
        __m256i p0 = _mm256_loadu_si256((const __m256i*)(in+64*b));
        __m256i p1 = _mm256_loadu_si256((const __m256i*)(in+64*b+32));
        _mm256_storeu_si256((__m256i*)(out+64*b), _mm256_xor_si256(v0,p0));
        _mm256_storeu_si256((__m256i*)(out+64*b+32), _mm256_xor_si256(v1,p1));
    }
}

static void chacha20_8blocks(const unsigned int k[8], unsigned int n0, unsigned int n1, unsigned int n2,
                             unsigned int counter, const unsigned char in[512], unsigned char out[512]){
    __m256i x0,x1,x2,x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13,x14,x15;
    x0=_mm256_set1_epi32(0x61707865); x1=_mm256_set1_epi32(0x3320646e);
    x2=_mm256_set1_epi32(0x79622d32); x3=_mm256_set1_epi32(0x6b206574);
    x4=_mm256_set1_epi32(k[0]); x5=_mm256_set1_epi32(k[1]); x6=_mm256_set1_epi32(k[2]); x7=_mm256_set1_epi32(k[3]);
    x8=_mm256_set1_epi32(k[4]); x9=_mm256_set1_epi32(k[5]); x10=_mm256_set1_epi32(k[6]); x11=_mm256_set1_epi32(k[7]);
    x12=_mm256_setr_epi32(counter,counter+1,counter+2,counter+3,counter+4,counter+5,counter+6,counter+7);
    x13=_mm256_set1_epi32(n0); x14=_mm256_set1_epi32(n1); x15=_mm256_set1_epi32(n2);
    __m256i s0=x0,s1=x1,s2=x2,s3=x3,s4=x4,s5=x5,s6=x6,s7=x7,s8=x8,s9=x9,s10=x10,s11=x11,s12=x12,s13=x13,s14=x14,s15=x15;
    for(int i=0;i<10;i++){
        QR(x0,x4,x8,x12); QR(x1,x5,x9,x13); QR(x2,x6,x10,x14); QR(x3,x7,x11,x15);
        QR(x0,x5,x10,x15); QR(x1,x6,x11,x12); QR(x2,x7,x8,x13); QR(x3,x4,x9,x14);
    }
    __m256i w[16];
    w[0]=_mm256_add_epi32(x0,s0); w[1]=_mm256_add_epi32(x1,s1); w[2]=_mm256_add_epi32(x2,s2); w[3]=_mm256_add_epi32(x3,s3);
    w[4]=_mm256_add_epi32(x4,s4); w[5]=_mm256_add_epi32(x5,s5); w[6]=_mm256_add_epi32(x6,s6); w[7]=_mm256_add_epi32(x7,s7);
    w[8]=_mm256_add_epi32(x8,s8); w[9]=_mm256_add_epi32(x9,s9); w[10]=_mm256_add_epi32(x10,s10); w[11]=_mm256_add_epi32(x11,s11);
    w[12]=_mm256_add_epi32(x12,s12); w[13]=_mm256_add_epi32(x13,s13); w[14]=_mm256_add_epi32(x14,s14); w[15]=_mm256_add_epi32(x15,s15);
    store_xor_8(w, in, out);
}

int main(){
    size_t N = 40960000; N -= N%512;
    unsigned char *in = aligned_alloc(64, N), *out = aligned_alloc(64, N);
    memset(in,1,N);
    unsigned int k[8]; memset(k,2,32);
    unsigned int n0=0x03030303,n1=0x03030303,n2=0x03030303;
    for(size_t off=0; off<4096; off+=512) chacha20_8blocks(k,n0,n1,n2,(unsigned)(off/64)+1,in+off,out+off);
    double t0=now(); int reps=4;
    for(int r=0;r<reps;r++)
        for(size_t off=0; off<N; off+=512) chacha20_8blocks(k,n0,n1,n2,(unsigned)(off/64)+1,in+off,out+off);
    double dt=now()-t0;
    printf("v2: %.1f ms/op, %.0f MB/s\n", dt/reps*1000, reps*(N/1e6)/dt);
    return 0;
}
EOF
