#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <immintrin.h>
#include <openssl/evp.h>
static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec/1e9;}
#define ROT(v,n) (_mm256_or_si256(_mm256_slli_epi32(v,n), _mm256_srli_epi32(v,32-(n))))
#define QR(a,b,c,d) do{ a=_mm256_add_epi32(a,b); d=_mm256_xor_si256(d,a); d=ROT(d,16); \
 c=_mm256_add_epi32(c,d); b=_mm256_xor_si256(b,c); b=ROT(b,12); \
 a=_mm256_add_epi32(a,b); d=_mm256_xor_si256(d,a); d=ROT(d,8); \
 c=_mm256_add_epi32(c,d); b=_mm256_xor_si256(b,c); b=ROT(b,7);} while(0)

/* After column rounds, lane layout is words. We store by transposing 8x8 blocks of 32-bit words.
   w[0..7] hold words 0..7 across 8 blocks; w[8..15] hold words 8..15. */
static inline void transpose8x8(__m256i *r){
    __m256i t[8];
    t[0]=_mm256_unpacklo_epi32(r[0],r[1]); t[1]=_mm256_unpackhi_epi32(r[0],r[1]);
    t[2]=_mm256_unpacklo_epi32(r[2],r[3]); t[3]=_mm256_unpackhi_epi32(r[2],r[3]);
    t[4]=_mm256_unpacklo_epi32(r[4],r[5]); t[5]=_mm256_unpackhi_epi32(r[4],r[5]);
    t[6]=_mm256_unpacklo_epi32(r[6],r[7]); t[7]=_mm256_unpackhi_epi32(r[6],r[7]);
    __m256i u[8];
    u[0]=_mm256_unpacklo_epi64(t[0],t[2]); u[1]=_mm256_unpackhi_epi64(t[0],t[2]);
    u[2]=_mm256_unpacklo_epi64(t[1],t[3]); u[3]=_mm256_unpackhi_epi64(t[1],t[3]);
    u[4]=_mm256_unpacklo_epi64(t[4],t[6]); u[5]=_mm256_unpackhi_epi64(t[4],t[6]);
